int f(int a) { static const int at[12] = {8192,4836,2555,1297,651,326,163,81,41,20,10,5}; int z = a, x = 9949, y = 0, i, q = 0; if (z > 0x4000) { z -= 0x4000; q = 1; } else if (z < -0x4000) { z += 0x4000; q = 2; } for (i = 0; i < 12; i++) { int xr = x >> i, yr = y >> i;   if (z >= 0) { x -= yr; y += xr; z -= at[i]; } else { x += yr; y -= xr; z += at[i]; } } if (q == 1) return x; if (q == 2) return -x; return y; }
